def solve_latin_square(grid):
    n = 10

    def is_valid(r, c, val):
        for i in range(n):
            if grid[r * n + i] == val: return False
            if grid[i * n + c] == val: return False
        return True

    def backtrack():
        for i in range(n * n):
            if grid[i] == -1:
                for val in range(n):
                    if is_valid(i // n, i % n, val):
                        grid[i] = val
                        if backtrack():
                            return True
                        grid[i] = -1
                return False
        return True

    if backtrack():
        return grid
    else:
        return None

